use super::*;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneStep,RetirementDemand,retirement::RetireOwned,shared_issuance::SealedShared};
use semio_framework_value_native_owned::{NativeDecodeControl,NativeReceive,OriginalReceivingPrimary,owned::NativeReceivingOriginal};
#[path="../../🫴️receiving/🎟️work/🧪️tests/📥️bank/🦀️.rs"]mod funding;
use funding::{Bank,observe};
fn bank()->Bank{let row:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::repo_text!("🧰️framework/🔨️modules/🗣️dsl/🧬️schema/🫴️receiving/📥️owned/🎟️work/📐️.json")).unwrap();Bank::new(&row["stock"])}
fn advance<A:RetireOwned+Sync,T:NativeReceive<A>>(receiver:&mut NativeReceivingOriginal<A,T>,control:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant,bank:&mut Bank)->Result<RetainedCloneStep,OriginalReceivingPrimary>{let(turn,h)=observe(||funding::receive(control,g,|native|receiver.advance(native,4096,g)));let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());bank.post(g,p,turn.work,h);turn.result}
fn take<A:RetireOwned+Sync,T:NativeReceive<A>>(receiver:&mut NativeReceivingOriginal<A,T>,bank:&mut Bank)->T{let g=bank.grant(4096);let(turn,h)=observe(||receiver.take(g));let p=match &turn.result{Ok(Some((_,p)))=>*p,Ok(None)=>Default::default(),Err(e)=>e.retained_progress()};bank.post(g,p,turn.work,h);turn.result.unwrap().unwrap().0}
fn close<A:RetireOwned+Sync,T:NativeReceive<A>>(receiver:&mut NativeReceivingOriginal<A,T>,bank:&mut Bank,limit:usize){receiver.begin_close();for _ in 0..limit{if receiver.terminal_is_empty(){return}let d=receiver.close_demands(4096).unwrap();assert!(d.copy_bytes<=4096);let g=bank.grant(4096);let(turn,h)=observe(||receiver.close_step(g));let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());bank.post(g,p,turn.work,h);turn.result.unwrap();}panic!("original DSL native receiver did not close under its original bound")}
#[test]
fn native_record_receive_borrows_actual_text_ordinals_and_payloads(){
 let law:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::repo_text!("🧰️framework/🔨️modules/🌱️value/🛬️decode/🧳️owned/🧩️record/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut original=RecordValue::default();for pair in law["text"].as_array().unwrap(){let ordinal=u16::try_from(pair[0].as_u64().unwrap()).unwrap();original.fields.insert(ordinal,if let Some(text)=pair[1].as_str(){FieldValue::Text(text.into())}else{FieldValue::Int(pair[1].as_i64().unwrap())});}assert_eq!(original.record_len().unwrap(),3);
 for index in 0..3{let NativeRecordKey::Ordinal(ordinal)=original.record_key(index).unwrap()else{panic!("text field lost actual ordinal")};assert_eq!(usize::from(ordinal),index);let name=law["fields"][index]["name"].as_str().unwrap();if index<2{let text=original.record_child(index).unwrap().text().unwrap();let FieldValue::Text(actual)=original.get(ordinal).unwrap()else{panic!("actual text changed")};assert_eq!(std::ptr::from_ref(text),std::ptr::from_ref(actual));assert_eq!(text,law["expected"][name].as_str().unwrap());}else{assert_eq!(original.record_child(index).unwrap().number().unwrap().as_i64(),law["expected"][name].as_i64());}}
 assert!(original.record_key(3).is_err());assert!(original.record_child(2).unwrap().text().is_err());assert!(original.record_child(0).unwrap().number().is_err());
let mut bank=bank();funding::close(original,&mut bank);
}

#[derive(semio_framework_value::RetireOwned,semio_framework_value::NativeReceive)]
struct NativeRow{id:SealedShared<String>,name:SealedShared<String>,value:i64}


fn actual_input(law:&serde_json::Value)->RecordValue{let mut record=RecordValue::default();for pair in law["text"].as_array().unwrap(){record.fields.insert(u16::try_from(pair[0].as_u64().unwrap()).unwrap(),if let Some(text)=pair[1].as_str(){FieldValue::Text(text.into())}else{FieldValue::Int(pair[1].as_i64().unwrap())});}record}
#[test]
fn native_record_receive_constructs_original_text_members_and_closes_every_frontier(){let law:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::repo_text!("🧰️framework/🔨️modules/🌱️value/🛬️decode/🧳️owned/🧩️record/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut finished=0;for cut in 0..128{let mut bank=bank();let source=funding::source(actual_input(&law),&mut bank);let(mut receiver,h)=observe(||NativeReceivingOriginal::<RecordValue,NativeRow>::new(source));assert_eq!(h,(0,0));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let mut turns=0;while turns<cut&&!receiver.output_ready(){let d=receiver.demands(4096).unwrap();let g=bank.grant(4096);for denied in funding::denied(g,d){let(turn,h)=observe(||funding::receive(&mut control,denied,|native|receiver.advance(native,4096,denied)));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(receiver.demands(4096).unwrap(),d);}advance(&mut receiver,&mut control,g,&mut bank).unwrap();turns+=1;}if receiver.output_ready(){finished=turns;let row=take(&mut receiver,&mut bank);assert_eq!(row.id.as_str(),law["expected"]["id"].as_str().unwrap());assert_eq!(row.name.as_str(),law["expected"]["name"].as_str().unwrap());assert_eq!(row.value,law["expected"]["value"].as_i64().unwrap());assert_eq!(serde_json::json!({"id":row.id.as_str(),"name":row.name.as_str(),"value":row.value}),law["expected"]);funding::close(row,&mut bank);}close(&mut receiver,&mut bank,10000);if finished>0&&cut>finished{break}}assert!(finished>0);}

#[derive(semio_framework_value::RetireOwned,semio_framework_value::NativeReceive)]
#[value(rename_all="camelCase")]
struct OriginalNested{label:String,count:u32}
#[derive(semio_framework_value::RetireOwned,semio_framework_value::NativeReceive)]
#[value(tag="kind",rename_all="camelCase")]
enum OriginalStatement{Nested(OriginalNested),Mark{label:String,count:u32}}
#[test]fn genuine_tagged_records_receive_original_ordinal_payloads_without_wire_conversion(){for tag in ["nested","mark"]{let mut bank=bank();let mut record=RecordValue::default();record.fields.insert(0,FieldValue::Text("original nested".into()));record.fields.insert(1,FieldValue::UInt(7));let authority=(tag.to_owned(),record);let source=funding::source(authority,&mut bank);let mut receiver=NativeReceivingOriginal::<(String,RecordValue),OriginalStatement>::new(source);let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);for _ in 0..1024{if receiver.output_ready(){break}let d=receiver.demands(4096).unwrap();let denied=RetainedCloneGrant{maximum_items:0,..bank.grant(4096)};let(turn,h)=observe(||funding::receive(&mut control,denied,|native|receiver.advance(native,4096,denied)));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(receiver.demands(4096).unwrap(),d);let g=bank.grant(4096);advance(&mut receiver,&mut control,g,&mut bank).unwrap();}assert!(receiver.output_ready());let value=take(&mut receiver,&mut bank);match &value{OriginalStatement::Nested(row)=>{assert_eq!(tag,"nested");assert_eq!(row.label,"original nested");assert_eq!(row.count,7)},OriginalStatement::Mark{label,count}=>{assert_eq!(tag,"mark");assert_eq!(label,"original nested");assert_eq!(*count,7)}}funding::close(value,&mut bank);close(&mut receiver,&mut bank,1024);}}

#[test]
fn original_paged_octets_lend_their_actual_native_children(){
 let law:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::repo_text!("🧰️framework/🔨️modules/🗣️dsl/🧬️schema/🛬️receive/🧪️tests/🧫️fixtures/📦️bytes.json")).unwrap();let bytes=law["bytes"].as_array().unwrap().iter().map(|value|u8::try_from(value.as_u64().unwrap()).unwrap()).collect::<Vec<_>>();let original=FieldValue::Bytes64(super::super::RecordBytes::try_from_slice(&bytes).unwrap());let FieldValue::Bytes64(owner)=&original else{unreachable!()};
 let((),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{assert_eq!(original.sequence_len().unwrap(),bytes.len());for(index,expected)in law["expected"].as_array().unwrap().iter().enumerate(){let child=original.sequence_child(index).unwrap();let retained=owner.retained_bytes().get(index).unwrap()as &dyn NativeValueSource;assert!(std::ptr::eq(child,retained));assert_eq!(child.number().unwrap().as_u64(),expected.as_u64());}assert!(original.sequence_child(bytes.len()).is_err());});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let mut bank=bank();funding::close(original,&mut bank);
}
